using Contoso.Pricing;

namespace Contoso.Pricing.Tests;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator = new();

    #region CalculateTotal - DataRow tests

    [TestMethod]
    [DataRow(10.00, 1, 0.0, 10.00, DisplayName = "Single item, no tax")]
    [DataRow(10.00, 5, 0.0, 50.00, DisplayName = "Multiple items, no tax")]
    [DataRow(25.00, 2, 0.10, 55.00, DisplayName = "Two items with 10% tax")]
    [DataRow(99.99, 3, 0.08, 323.97, DisplayName = "Three items with 8% tax")]
    [DataRow(0.00, 10, 0.20, 0.00, DisplayName = "Zero price")]
    [DataRow(50.00, 0, 0.15, 0.00, DisplayName = "Zero quantity")]
    [DataRow(100.00, 1, 1.0, 200.00, DisplayName = "100% tax rate")]
    public void CalculateTotal_WithValidInputs_ReturnsExpectedTotal(
        double unitPrice, int quantity, double taxRate, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)unitPrice, quantity, (decimal)taxRate);

        Assert.AreEqual((decimal)expected, result, $"Expected {expected} but got {result}");
    }

    #endregion

    #region CalculateTotal - Exception tests

    [TestMethod]
    [DataRow(-1, DisplayName = "Negative quantity")]
    public void CalculateTotal_NegativeQuantity_Throws(int quantity)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(10m, quantity, 0.1m));

        Assert.AreEqual("quantity", ex.ParamName);
    }

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Slightly negative price")]
    [DataRow(-100.00, DisplayName = "Large negative price")]
    public void CalculateTotal_NegativeUnitPrice_Throws(double unitPrice)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal((decimal)unitPrice, 1, 0.1m));

        Assert.AreEqual("unitPrice", ex.ParamName);
    }

    [TestMethod]
    [DataRow(-0.01, DisplayName = "Negative tax rate")]
    [DataRow(1.01, DisplayName = "Tax rate above 1")]
    public void CalculateTotal_InvalidTaxRate_Throws(double taxRate)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculateTotal(10m, 1, (decimal)taxRate));

        Assert.AreEqual("taxRate", ex.ParamName);
    }

    #endregion

    #region ApplyDiscount - DynamicData with ValueTuples

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithValidInputs_ReturnsExpectedPrice(
        decimal price, decimal discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, decimal discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 0m, 100m),       // No discount
        (100m, 10m, 90m),       // 10% off
        (100m, 50m, 50m),       // Half price
        (100m, 100m, 0m),       // Free
        (249.99m, 25m, 187.4925m), // Fractional result
        (0m, 50m, 0m),          // Zero price with discount
    ];

    #endregion

    #region ApplyDiscount - Invalid discount boundary tests

    [TestMethod]
    [DataRow(-1.0, DisplayName = "Negative discount")]
    [DataRow(100.01, DisplayName = "Discount above 100%")]
    [DataRow(200.0, DisplayName = "Discount of 200%")]
    public void ApplyDiscount_InvalidDiscountPercent_Throws(double discountPercent)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, (decimal)discountPercent));

        Assert.AreEqual("discountPercent", ex.ParamName);
    }

    #endregion

    #region FormatPrice - DynamicData with display names

    [TestMethod]
    [DynamicData(nameof(FormatPriceTestData))]
    public void FormatPrice_WithVariousInputs_ReturnsFormattedString(
        decimal price, string currencySymbol, string expected)
    {
        var result = _calculator.FormatPrice(price, currencySymbol);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, string currencySymbol, string expected)> FormatPriceTestData =>
    [
        (19.99m, "$", "$19.99"),
        (1000m, "€", "€1000.00"),
        (0m, "£", "£0.00"),
        (9.999m, "$", "$10.00"),   // Rounding
    ];

    #endregion
}

